class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        INF = float('inf')
        mn = [[INF] * n for _ in range(m)]
        ans = -INF
        for i in range(m):
            for j in range(n):
                pred = min(mn[i-1][j] if i else INF,
                           mn[i][j-1] if j else INF)
                if pred < INF:
                    ans = max(ans, grid[i][j] - pred)
                mn[i][j] = min(grid[i][j], pred)
        return ans

