class Solution {
public:
    int maxScore(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        const int INF = INT_MAX;
        vector<vector<int>> mn(m, vector<int>(n, INF));
        long long ans = LLONG_MIN;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                int pred = INF;
                if (i) pred = min(pred, mn[i-1][j]);
                if (j) pred = min(pred, mn[i][j-1]);
                if (pred != INF) ans = max(ans, (long long)grid[i][j] - pred);
                mn[i][j] = min(grid[i][j], pred);
            }
        return (int) ans;
    }
};

