class Solution {
    public int maxScore(List<List<Integer>> grid) {
        int m = grid.size(), n = grid.get(0).size();
        int[][] mn = new int[m][n];
        for (int[] r : mn) Arrays.fill(r, Integer.MAX_VALUE);
        long ans = Long.MIN_VALUE;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                int pred = Integer.MAX_VALUE;
                if (i > 0) pred = Math.min(pred, mn[i-1][j]);
                if (j > 0) pred = Math.min(pred, mn[i][j-1]);
                if (pred != Integer.MAX_VALUE)
                    ans = Math.max(ans, (long) grid.get(i).get(j) - pred);
                mn[i][j] = Math.min(grid.get(i).get(j), pred);
            }
        return (int) ans;
    }
}

